# -*- coding: utf-8 -*-
import os
import fcntl
import select


class TimeboxedReader(object):
    def __init__(self, stream):
        self._stream = stream
        fcntl.fcntl(self._stream.fileno(), fcntl.F_SETFL, os.O_NONBLOCK)

    def read(self, timeout):
        rl, _, _ = select.select([self._stream], [], [], timeout)
        data = self._stream.read() if rl else None
        return data.decode() if data else data

    def close(self):
        self._stream.close()
